function proofCost(d):
  assert d >= 1
  m <- d ; p <- 2 ; count <- 0
  while p*p <= m:
    while m mod p == 0:
      count <- count + 1 ; m <- m / p
    p <- p + 1
  if m > 1: count <- count + 1   # remaining prime factor
  return count

