function antiGravityCertificate(N, d, c):
  cost <- proofCost(d)
  cost_ok    <- cost <= c
  ceiling_ok <- (N // d) <= (N // 2^c)
  tradeoff   <- (N // d) <= (N // 2^cost)   # always true (Thm 4.2)
  return (cost_ok, ceiling_ok, tradeoff)

function topAntiGravity(N, budget, top):
  out <- [] ; d <- 1
  while |out| < top and d <= N:
    if proofCost(d) <= budget:
      out.append( (d, proofCost(d), N // d) )
    d <- d + 1
  return out   # already sorted by descending support
